import { accuracyToPercent } from '06_shared/utils/accuracyToPercent';
// «Move 76% · Dir 81%» з відносних метрик сигналу. Кожна частина — лише
// коли метрика є; без обох — null (legacy-нейрон чи старий сигнал).
export const formatRelativeMetrics = (signal, t) => {
    const parts = [];
    if (signal.signal_move_relative != null) {
        parts.push(`${t('Move')} ${accuracyToPercent(signal.signal_move_relative, 0)}`);
    }
    if (signal.signal_direction_relative != null) {
        parts.push(`${t('Dir')} ${accuracyToPercent(signal.signal_direction_relative, 0)}`);
    }
    return parts.length ? parts.join(' · ') : null;
};
